s_source":{"publisher_label":"Typical Analysis","source_format":"pdf","source_url":"https://cdn.frommfamily.com/products/ta/3620_211348_cat-can_purrsnickitty-shredded-chicken-entree-in-gelee_nutrition.pdf","status":"requires_verified_extraction"}},{"cache_key":"fromm-family-foods:fromm purrsnickitty tuna shrimp in gel e wet cat food","typical_analysis":null,"published_analysis_source":{"publisher_label":"Typical Analysis","source_format":"pdf","source_url":"https://cdn.frommfamily.com/products/ta/3620_211352_cat-can_purrsnickitty-tuna-and-shrimp-entree-in-gelee_nutrition.pdf","status":"requires_verified_extraction"}},{"cache_key":"fromm-family-foods:fromm reduced activity senior gold dog food","typical_analysis":{"protein":26.17,"fat":12.89,"fiber":4.31,"ash":6.15,"calcium":1.42,"phosphorus":1.09,"analysis_type":"typical","basis":"dry_matter","source_url":"https://cdn.frommfamily.com/products/ta/f2349_211540_dog-dry-gold-reduced-activity-senior_20231019.pdf","source_format":"pdf_text","publisher_label":"Typical Analysis"},"published_analysis_source":{"status":"extracted","analysis_type":"typical","basis":"dry_matter","publisher_label":"Typical Analysis","source_format":"pdf_text","source_url":"https://cdn.frommfamily.com/products/ta/f2349_211540_dog-dry-gold-reduced-activity-senior_20231019.pdf"}}]$published_analysis$::jsonb) AS patch(
      cache_key TEXT,
      typical_analysis JSONB,
      published_analysis_source JSONB
    )
  )
  UPDATE public.product_data AS product
  SET nutritional_info = COALESCE(product.nutritional_info, '{}'::jsonb)
      || jsonb_strip_nulls(jsonb_build_object(
        'typical_analysis', patches.typical_analysis,
        'published_analysis_source', patches.published_analysis_source
      )),
      has_published_nutrients = TRUE,
      updated_at = NOW()
  FROM patches
  WHERE product.cache_key = patches.cache_key;

  GET DIAGNOSTICS v_updated = ROW_COUNT;
  IF v_updated <> 291 THEN
    RAISE EXCEPTION 'Expected to enrich 291 exact product rows, updated %', v_updated;
  END IF;
END;
